CREATE TRIGGER scenario_versions_immutable BEFORE UPDATE ON scenario_versions FOR EACH ROW BEGIN IF NOT (OLD.definition <=> NEW.definition) OR NOT (OLD.version_no <=> NEW.version_no) OR NOT (OLD.scenario_id <=> NEW.scenario_id) OR NOT (OLD.kind <=> NEW.kind) OR NOT (OLD.compiler_version <=> NEW.compiler_version) OR NOT (OLD.source_digest <=> NEW.source_digest) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'scenario_versions immutable'; END IF; END;

CREATE TRIGGER runs_snapshot_immutable BEFORE UPDATE ON runs FOR EACH ROW BEGIN IF NOT (OLD.snapshot <=> NEW.snapshot) OR NOT (OLD.snapshot_digest <=> NEW.snapshot_digest) OR NOT (OLD.target_id <=> NEW.target_id) OR NOT (OLD.scenario_id <=> NEW.scenario_id) OR NOT (OLD.scenario_version_id <=> NEW.scenario_version_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'runs immutable'; END IF; END;

CREATE TRIGGER attempts_closed_immutable BEFORE UPDATE ON attempts FOR EACH ROW BEGIN IF OLD.status IN ('SUCCEEDED', 'FAILED', 'CANCELLED') AND (NOT (OLD.status <=> NEW.status) OR NOT (OLD.output <=> NEW.output) OR NOT (OLD.error <=> NEW.error) OR NOT (OLD.finished_at <=> NEW.finished_at)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'attempts immutable'; END IF; END;
